-- Innovation Talks are in the Expo Hall (Aryabhata Theatre), unless a hall is already set
-- or the agenda puts the talk in another hall (CGI, Intangles, Joget, LightMetrics, Maharashtra Forest Department, Ministry of Tribal Affairs, NoBroker, Nu10 Technologies).
UPDATE innovation_talks SET hall = 'Aryabhata Theatre' WHERE event_id = 1 AND trim(ifnull(hall, '')) = '' AND company NOT IN ('CGI', 'Intangles', 'Joget', 'LightMetrics', 'Maharashtra Forest Department', 'Ministry of Tribal Affairs', 'NoBroker', 'Nu10 Technologies');

